#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

# Go live on uselattice.app (T51). docs/deploy.md explains every setting; this walks through them in order.
#
#   scripts/go-live-wizard.sh        # from the start
#   scripts/go-live-wizard.sh 14     # from stage 14; earlier values come back from web/.env.production

cd "$(dirname "$0")/.."
ENV_FILE="web/.env.production"
DOMAIN="uselattice.app"
SITE="https://$DOMAIN"
REGION="ap-south-1"
CF="https://dash.cloudflare.com/?to=/:account"
LAMBDA="https://$REGION.console.aws.amazon.com/lambda/home?region=$REGION#/functions"

# show "value" prints a value to copy, on its own line.
show() { printf '\n      %s%s%s\n\n' "$BOLD" "$1" "$RESET"; }

# load_supabase sets REF, DASH and CALLBACK from VITE_SUPABASE_URL, as stage 6 saved it.
load_supabase() {
  [[ -n "${VITE_SUPABASE_URL:-}" ]] || VITE_SUPABASE_URL=$(_existing VITE_SUPABASE_URL || true)
  [[ -n "$VITE_SUPABASE_URL" ]] || { warn "No VITE_SUPABASE_URL in $ENV_FILE yet: run stage 6 first."; exit 1; }
  REF="${VITE_SUPABASE_URL#https://}"; REF="${REF%%.*}"
  DASH="https://supabase.com/dashboard/project/$REF"
  CALLBACK="$VITE_SUPABASE_URL/auth/v1/callback"
}

# until_ok "what" CMD...: runs CMD until it succeeds, or the human gives up waiting (then carries on).
until_ok() {
  local what="$1"; shift
  while ! "$@"; do
    warn "Not yet: $what."
    confirm "Check again? (No carries on without it)" || { SKIPPED+=("$what"); return 0; }
  done
  printf '  %s✓%s %s\n' "$GREEN" "$RESET" "$what"
}

ns_is_cloudflare() { dig +short NS "$DOMAIN" @1.1.1.1 | grep -q 'ns.cloudflare.com'; }
www_redirects() {
  curl -sI --max-time 10 "https://www.$DOMAIN/help?x=1" | tr -d '\r' |
    grep -qi "^location: $SITE/help?x=1"
}
one_apex_spf() { [[ $(dig +short TXT "$DOMAIN" @1.1.1.1 | grep -c 'v=spf1') == 1 ]]; }
has_dmarc() { dig +short TXT "_dmarc.$DOMAIN" @1.1.1.1 | grep -q 'v=DMARC1'; }
aws_ok() { aws sts get-caller-identity >/dev/null 2>&1; }
fn_url() {
  local url
  url=$(aws lambda get-function-url-config --region "$REGION" --function-name "$1" --query FunctionUrl --output text)
  printf '%s' "${url%/}"
}
site_serves_app() { curl -sf --max-time 10 "$SITE/privacy" | grep -q 'Version'; }

# ── 1 ─────────────────────────────────────────────────────────────────────
s_zone() {
stage "Cloudflare: add the domain"
say "Cloudflare will run DNS for $DOMAIN, serve the site and forward privacy@. The domain stays"
say "registered at Name.com."
open_url "$CF/add-site"
step "Sign up or log in. Enter $DOMAIN, pick the Free plan, Continue."
step "On the DNS records it found: delete Name.com's parking A record (and any other parking"
step "records). Nothing else should be there; the domain had no mail records."
step "Continue until Cloudflare shows two nameservers (like ada.ns.cloudflare.com). Keep that tab open."
pause "Press Enter when you can see the two nameservers."
}

# ── 2 ─────────────────────────────────────────────────────────────────────
s_nameservers() {
stage "Name.com: nameservers and auto-renew"
open_url "https://www.name.com/account/domain/details/$DOMAIN"
step "If DNSSEC is on for $DOMAIN, turn it off first (Cloudflare can turn on its own later)."
step "Nameservers → Manage → remove Name.com's and enter Cloudflare's two. Save."
step "Turn on Auto-renew for $DOMAIN (it expires 24 Oct 2027)."
step "Back in Cloudflare, click Check nameservers."
pause "Press Enter when both are saved."
say "Waiting for the new nameservers to show in DNS. Usually minutes, sometimes hours."
until_ok "$DOMAIN uses Cloudflare's nameservers" ns_is_cloudflare
note "Cloudflare emails you when the domain is Active; later stages need it."
pause
}

# ── 3 ─────────────────────────────────────────────────────────────────────
s_www() {
stage "Cloudflare: www → $DOMAIN"
say "www gets a placeholder record so Cloudflare answers for it, and a rule sends it to the apex."
open_url "$CF/:zone/dns/records"
step "Pick $DOMAIN if asked. Add record: Type AAAA, Name www, IPv6 address 100::, Proxy status"
step "Proxied (orange cloud). Save."
pause "Press Enter when the www record is saved."
open_url "$CF/:zone/rules/redirect-rules"
step "Create rule. If a template \"Redirect from WWW to root\" is offered, use it and check it"
step "keeps the path and query string. Otherwise, a custom rule:"
step "  Name: www to apex. Custom filter expression: Hostname equals www.$DOMAIN"
step "  Then: Dynamic, expression:"
show "concat(\"$SITE\", http.request.uri.path)"
step "  Status code 301, Preserve query string ticked. Deploy."
pause "Press Enter when the rule is deployed."
until_ok "https://www.$DOMAIN redirects to $SITE" www_redirects
pause
}

# ── 4 ─────────────────────────────────────────────────────────────────────
s_routing() {
stage "Cloudflare: privacy@$DOMAIN"
say "The privacy policy gives privacy@$DOMAIN; Email Routing forwards it to your inbox."
open_url "$CF/:zone/email/routing"
step "Get started (or Routing rules → Create address). Custom address: privacy."
step "Destination: your own inbox. Cloudflare emails it a verification link: click it."
step "When asked, let Cloudflare add its MX and SPF records. Catch-all stays off."
pause "Press Enter when privacy@ shows as Active and your inbox is Verified."
}

# ── 5 ─────────────────────────────────────────────────────────────────────
s_resend() {
stage "Resend: send from $DOMAIN"
say "Supabase sends sign-in links through Resend, as Lattice <no-reply@$DOMAIN>."
open_url "https://resend.com/domains"
step "Sign up or log in. Add Domain: $DOMAIN, region left at the default."
step "If Resend offers to add the records to Cloudflare for you, accept. Otherwise add each record"
step "it lists in Cloudflare's DNS (Proxy status: DNS only), exactly as shown."
note "Resend's SPF and MX go on send.$DOMAIN, Cloudflare's SPF on $DOMAIN itself: different names,"
note "so each keeps its own record. Never add a second v=spf1 record on the same name."
step "Click Verify DNS Records and wait for Verified."
pause "Press Enter when the domain shows Verified."
open_url "$CF/:zone/dns/records"
step "Add record: Type TXT, Name _dmarc, content:"
show "v=DMARC1; p=none; rua=mailto:privacy@$DOMAIN"
step "Save. (If a _dmarc record exists already, edit it to that instead.)"
pause "Press Enter when it's saved."
until_ok "one SPF record on $DOMAIN" one_apex_spf
until_ok "a DMARC record on _dmarc.$DOMAIN" has_dmarc
pause
}

# ── 6 ─────────────────────────────────────────────────────────────────────
s_supabase_project() {
stage "Supabase: production project"
say "Production gets its own free project in Mumbai, apart from dev."
open_url "https://supabase.com/dashboard/new"
step "Same organisation as dev. Name: lattice. Region: South Asia (Mumbai). Free plan."
step "Database password: Generate one and keep it in your password manager (stage 8 asks for it)."
step "Leave the security options at their defaults, as dev has them. Create new project."
step "When it's ready, click Connect at the top and copy the project URL."
while :; do
  ask VITE_SUPABASE_URL "Paste the production project URL:"
  VITE_SUPABASE_URL="${VITE_SUPABASE_URL%/}"
  [[ "$VITE_SUPABASE_URL" =~ ^https://[a-z]{20}\.supabase\.co$ ]] && break
  warn "That doesn't look like https://<20-letter ref>.supabase.co; try again."
done
if [[ "$VITE_SUPABASE_URL" == "$(grep -s '^VITE_SUPABASE_URL=' web/.env.local | cut -d= -f2- | tr -d "'\"")" ]]; then
  warn "That's the dev project from web/.env.local. Production needs the new one."
  exit 1
fi
write_env VITE_SUPABASE_URL "$VITE_SUPABASE_URL"
}

# ── 7 ─────────────────────────────────────────────────────────────────────
s_supabase_key() {
load_supabase
stage "Supabase: public key"
say "The web app's public key. It ships in every visitor's bundle; row-level security guards the data."
open_url "$DASH/settings/api-keys"
step "Copy the Publishable key (sb_publishable_…), or on Legacy API keys the anon key (eyJ…)."
warn "Never the secret / service_role key: this file is committed."
while :; do
  ask VITE_SUPABASE_ANON_KEY "Paste the publishable (or anon) key:"
  [[ "$VITE_SUPABASE_ANON_KEY" =~ ^(sb_publishable_|eyJ) ]] && break
  warn "Expected a key starting sb_publishable_ or eyJ; try again."
done
write_env VITE_SUPABASE_ANON_KEY "$VITE_SUPABASE_ANON_KEY"
}

# ── 8 ─────────────────────────────────────────────────────────────────────
s_migrate() {
load_supabase
stage "Supabase: tables and policies"
say "scripts/migrate-prod.sh applies supabase/migrations to production. It asks for the database"
say "password from stage 6 (lost it? $DASH/database/settings → Reset), shows what's"
say "missing and applies it after you type yes."
if ! npx --yes supabase projects list >/dev/null 2>&1; then
  say "First, log the Supabase CLI in (opens the browser):"
  npx --yes supabase login
fi
until_ok "migrations applied to $REF" scripts/migrate-prod.sh "$REF"
until_ok "production's schema_version() matches supabase/migrations" scripts/smoke.sh migrations
pause
}

# ── 9 ─────────────────────────────────────────────────────────────────────
s_auth_urls() {
load_supabase
stage "Supabase: sign-in URLs"
say "After a sign-in, Supabase only sends people back to listed addresses."
open_url "$DASH/auth/url-configuration"
step "Site URL:"
show "$SITE"
step "Save. Redirect URLs → Add URL:"
show "$SITE/**"
step "Save. No localhost entries: production is only for the live site."
pause "Press Enter when both are saved."
}

# ── 10 ────────────────────────────────────────────────────────────────────
s_smtp() {
load_supabase
stage "Supabase: email through Resend"
say "First a Resend key that may only send from $DOMAIN. It goes straight into Supabase;"
say "this wizard never sees it."
open_url "https://resend.com/api-keys"
step "Create API Key. Name: supabase-production. Permission: Sending access. Domain: $DOMAIN."
step "Copy the key (Resend shows it once)."
pause "Press Enter when it's copied."
open_url "$DASH/auth/smtp"
step "Turn on Enable Custom SMTP, then:"
step "  Sender email: no-reply@$DOMAIN    Sender name: Lattice"
step "  Host: smtp.resend.com    Port: 465    Username: resend    Password: the Resend key"
step "Save. Leave the email templates as they are (dev uses the defaults too)."
pause "Press Enter when SMTP is saved."
}

# ── 11 ────────────────────────────────────────────────────────────────────
s_mail_test() {
load_supabase
stage "Email: test both ways"
say "From the domain: Supabase sends an invite through Resend."
open_url "$DASH/auth/users"
step "Add user → Send invitation → your own address. Don't click the link in it."
step "In your inbox: it comes from Lattice <no-reply@$DOMAIN> and isn't in spam."
step "Gmail: ⋮ → Show original. SPF, DKIM and DMARC all say PASS."
step "Back in Supabase, delete that user."
pause "Press Enter when the invite arrived and passed."
say "To the domain: privacy@ forwards."
step "From a different account (Gmail hides mail you send to yourself), email privacy@$DOMAIN."
step "It arrives in your inbox, not spam."
confirm "Did both mails arrive in the inbox, with SPF, DKIM and DMARC passing?" ||
  SKIPPED+=("email test: check Resend's DNS (stage 5) and the SMTP settings (stage 10)")
}

