# ── 14 ────────────────────────────────────────────────────────────────────
s_aws() {
stage "AWS: the functions"
say "scripts/aws-setup.sh makes the image repository, both functions with their URLs, the deploy"
say "role for GitHub and a \$5 budget alert, in Mumbai. With an empty repository it builds the first"
say "image here with podman (a few minutes)."
if ! aws_ok; then
  say "First, log the AWS CLI in (opens the browser):"
  aws login --region "$REGION" || true
fi
until_ok "logged in to AWS" aws_ok
local budget_email=""
while [[ "$budget_email" != *@* ]]; do
  ask budget_email "Email address for the budget alert:"
done
until_ok "scripts/aws-setup.sh finished" scripts/aws-setup.sh "$budget_email"
write_env VITE_SOLVER_URL "$(fn_url lattice-solver)"
write_env VITE_AGENT_URL "$(fn_url lattice-agent)"
pause
}

# ── 15 ────────────────────────────────────────────────────────────────────
s_solver_env() {
stage "AWS: solver settings"
say "Set by hand in the console, never by a deploy. The solver gets no keys."
aws lambda get-account-settings --region "$REGION" \
  --query 'AccountLimit.{concurrency:ConcurrentExecutions}' --output text |
  sed 's/^/  Concurrent executions allowed: /'
note "The function is 3,008 MB with 2 workers. If AWS support has approved 10,240 MB by now, set"
note "Memory to 7168 MB on Configuration → General configuration and SOLVER_WORKERS to 4 below."
open_url "$LAMBDA/lattice-solver?tab=configure"
step "Configuration → Environment variables → Edit → Add, these two, then Save:"
show "SOLVER_WORKERS = 2"
show "CORS_ORIGINS = $SITE"
pause "Press Enter when they're saved."
}

