pause "Press Enter when the project exists."
}

# ── 18 ────────────────────────────────────────────────────────────────────
s_hook() {
stage "Cloudflare Pages: deploy only after CI"
say "GitHub's deploy workflow calls a deploy hook after the tests pass, so Pages must not build"
say "every push by itself."
step "In the project: Settings → Build → Branch control."
step "Production branch main; untick Enable automatic production branch deployments."
step "Preview branch: None. Save."
step "Same page, Deploy hooks → Add: name github-deploy, branch main. Copy its URL."
local PAGES_DEPLOY_HOOK=""
ask_secret PAGES_DEPLOY_HOOK "Paste the deploy hook URL (Enter if there is no Deploy hooks option):"
if [[ "$PAGES_DEPLOY_HOOK" == https://* ]]; then
  say "Trying it: does the hook build main with automatic deploys off?"
  curl -fsS -X POST "$PAGES_DEPLOY_HOOK" >/dev/null && note "POSTed the hook."
  step "In the project's Deployments tab, a new production build of main should start."
  if confirm "Did a build start?"; then
    set_secret PAGES_DEPLOY_HOOK "$PAGES_DEPLOY_HOOK"
    return
  fi
  warn "The hook didn't build with automatic deploys off. Delete the hook in Pages."
fi
say "Then Pages builds main itself, tests first (decided 25 Oct; docs/deploy.md):"
step "Branch control: tick Enable automatic production branch deployments. Save."
step "Build configuration → Edit → Build command:"
show "npm ci && npm test && npx tsc -b && npm run build"
gh secret delete PAGES_DEPLOY_HOOK >/dev/null 2>&1 || true
SKIPPED+=("No deploy hook: tell Claude, so docs/deploy.md records automatic deploys")
pause "Press Enter when that's saved."
}

# ── 19 ────────────────────────────────────────────────────────────────────
s_custom_domain() {
stage "Cloudflare Pages: $DOMAIN"
step "In the project: Custom domains → Set up a custom domain → $DOMAIN → Continue → Activate."
note "The zone is in this account, so Cloudflare adds the DNS record itself. Only the apex: www"
note "redirects (stage 3)."
pause "Press Enter when it shows Active."
until_ok "$SITE/privacy serves the app's policy page" site_serves_app
pause
}

# ── 20 ────────────────────────────────────────────────────────────────────
s_consent() {
load_supabase
stage "Google Cloud: publish the consent screen"
say "Until it's published only test users can sign in with Google. Dev's client shares this screen."
open_url "https://console.cloud.google.com/auth/branding"
step "App name: Lattice. User support email: yours. App logo: none (a logo means brand verification)."
step "App domain: home page $SITE, privacy policy $SITE/privacy, terms $SITE/terms."
step "Authorized domains: add $DOMAIN and $REF.supabase.co (if Google refuses the second, skip it)."
step "Developer contact: yours. Save."
pause "Press Enter when the branding is saved."
open_url "https://console.cloud.google.com/auth/audience"
step "Publishing status: Publish app → Confirm. It should say In production, with no verification"
step "needed (Lattice asks only for name, email and profile picture)."
pause "Press Enter when it's In production."
}

# ── 21 ────────────────────────────────────────────────────────────────────
s_github() {
stage "GitHub: deploy settings"
local arn
arn=$(aws iam get-role --role-name lattice-deploy --query Role.Arn --output text)
set_var AWS_DEPLOY_ROLE_ARN "$arn"
local have
have=$(gh secret list --json name -q '.[].name' 2>/dev/null || true)
for s in SUPABASE_URL SUPABASE_ANON_KEY SUPABASE_SERVICE_ROLE_KEY PAGES_DEPLOY_HOOK; do
  if grep -qx "$s" <<<"$have"; then
    printf '  %s✓%s secret %s is set\n' "$GREEN" "$RESET" "$s"
  elif [[ $s == PAGES_DEPLOY_HOOK ]]; then
    note "  no PAGES_DEPLOY_HOOK: fine only if Pages deploys main by itself (stage 18)"
  else
    warn "secret $s is missing: the dev project's value, see docs/deploy.md → GitHub secrets"
    SKIPPED+=("GitHub secret $s (dev project)")
  fi
done
pause
}

STAGES=(s_zone s_nameservers s_www s_routing s_resend s_supabase_project s_supabase_key s_migrate s_auth_urls
  s_smtp s_mail_test s_google_client s_google_provider s_aws s_solver_env s_agent_env s_pages s_hook
  s_custom_domain s_consent s_github)
TOTAL_STAGES=${#STAGES[@]}
FROM=${1:-1}
if ! [[ "$FROM" =~ ^[0-9]+$ ]] || (( FROM < 1 || FROM > TOTAL_STAGES )); then
  echo "Usage: $0 [first stage, 1-$TOTAL_STAGES]" >&2; exit 2
fi

banner "Go live on $DOMAIN (T51)"
_STAGE_INDEX=$((FROM - 1))
for s in "${STAGES[@]:FROM-1}"; do "$s"; done

finish
say "Values in $ENV_FILE. Next, with Claude: commit it, merge to main and watch deploy.yml,"
say "then the click-through on the live site (tickets/T51-go-live.md, step 9)."
printf '\n'
}

run_wizard "$@"; exit
